<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\TenantTermsOfUseRef;
use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\ValueObject\Accessor\UserAcceptedTermsOfUseConditionsAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserAcceptedTermsOfUseConditionsAccessor trait.
 *
 * Covers null default, string/VO assignment via withConditions,
 * getConditions/conditions accessors, and isConditionsChanged with/without original.
 */
class UserAcceptedTermsOfUseConditionsAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withConditions creates a new instance with the Conditions set
     * from a string value, and getConditions returns the primitive string.
     */
    public function testWithConditionsFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserAcceptedTermsOfUseConditionsAccessorUnitTest();

        // Act
        $result = $holder->withConditions(new TenantTermsOfUseRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new TenantTermsOfUseRef('one'), $result->getConditions());
    }
    /**
     * Asserts that withconditions has access to the value object
     * from a string value, and getConditions returns the primitive string.
     */
    public function testWithConditionsFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserAcceptedTermsOfUseConditionsAccessorUnitTest();

        // Act
        $result = $holder->withConditions(new TenantTermsOfUseRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new TenantTermsOfUseRef('one'), $result->conditions()->value());
    }
    public function testChangedConditions(): void
    {
        // Arrange
        $holder = new ImplWithUserAcceptedTermsOfUseConditionsAccessorUnitTest()->withConditions(new TenantTermsOfUseRef('one'));
        $original = $holder->withConditions(new TenantTermsOfUseRef('one'));
        $same = $holder->withConditions(new TenantTermsOfUseRef('one'));
        $modified = $holder->withConditions(new TenantTermsOfUseRef('other'));

        // Act
        $withSame = $original->isConditionsChanged($same);
        $withDiferent = $original->isConditionsChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserAcceptedTermsOfUseConditionsAccessorUnitTest
{
    use UserAcceptedTermsOfUseConditionsAccessor;
}
